//! Canonical legend form metadata uses only the actual direct parent fieldset.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><fieldset id=fieldset><legend id=legend>Group</legend><input id=child value=seed></fieldset><legend id=outside>Outside</legend></form><form id=other></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://legend-form.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn legend_form_genuine_interface_readonly_descriptor_and_direct_parent(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('legend'),owner=document.getElementById('owner'),C=HTMLLegendElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'form');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||Object.getPrototypeOf(P)!==HTMLElement.prototype||Object.prototype.toString.call(x)!=='[object HTMLLegendElement]')throw 'genuine legend interface';if(!a||typeof a.get!=='function'||a.set!==undefined||!a.enumerable||!a.configurable||a.get.name!=='get form'||a.get.length!==0||Object.hasOwn(x,'form'))throw 'canonical readonly form';if(x.form!==owner||document.getElementById('outside').form!==null)throw 'direct fieldset parent only';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal legend constructor';");}
#[test]
fn legend_form_current_fieldset_owner_and_ignores_author_properties(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('legend'),fieldset=document.getElementById('fieldset'),owner=document.getElementById('owner'),other=document.getElementById('other'),get=Object.getOwnPropertyDescriptor(HTMLLegendElement.prototype,'form').get;fieldset.setAttribute('form','other');Object.defineProperty(fieldset,'form',{get:function(){throw 'author parent form';},configurable:true});Object.defineProperty(x,'parentNode',{get:function(){throw 'author parent';},configurable:true});if(get.call(x)!==other)throw 'actual parent association';var doc=new Document(),html='http://www.w3.org/1999/xhtml',f=doc.createElementNS(html,'fieldset'),l=doc.createElementNS(html,'legend'),o=doc.createElementNS(html,'form'),holder=doc.createElementNS(html,'div');o.appendChild(f);f.appendChild(l);f.appendChild(holder);if(get.call(l)!==o)throw 'actual inert parent owner';holder.appendChild(l);if(get.call(l)!==null)throw 'no ancestor search';f.appendChild(l);if(get.call(l)!==o)throw 'actual parent restored';");}
#[test]
fn legend_form_inert_exact_namespace_clone_and_adopt(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),owner=doc.createElementNS(html,'form'),fieldset=doc.createElementNS(html,'fieldset'),x=doc.createElementNS(html,'p:legend');doc.appendChild(root);root.appendChild(owner);root.appendChild(fieldset);fieldset.appendChild(x);owner.id='A\ud800z';fieldset.setAttribute('form','A\ud800z');if(!(x instanceof HTMLLegendElement)||x.form!==owner||x.cloneNode(false).form!==null)throw 'exact inert owner and clone';var target=new Document(),detached=target.createElementNS(html,'form');target.adoptNode(fieldset);detached.appendChild(fieldset);if(x.form!==detached||x.ownerDocument!==target)throw 'adopted actual direct parent';"#);}

#[test]
fn legend_form_readonly_brand_and_author_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),owner=document.getElementById('owner'),P=HTMLLegendElement.prototype,calls=0;for(var name of ['form']){var get=Object.getOwnPropertyDescriptor(P,name).get,expected=owner;x[name]={toString:function(){calls++;return 'bad';}};if(x[name]!==expected)throw 'readonly sloppy';var caught=false;try{(function(){'use strict';x[name]='bad';})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'readonly strict';for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','legend')]){caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine brand';}Object.defineProperty(x,name,{value:'author',configurable:true});if(x[name]!=='author'||get.call(x)!==expected)throw 'native authority';delete x[name];if(x[name]!==expected)throw 'native restore';}if(calls)throw 'readonly conversion';"#);}

#[test]
fn legend_form_namespace_enumeration_and_saved_constructor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('legend'),C=HTMLLegendElement,P=C.prototype,get=Object.getOwnPropertyDescriptor(P,'form').get,doc=new Document(),html='http://www.w3.org/1999/xhtml',prefixed=doc.createElementNS(html,'p:legend');if(!(prefixed instanceof C)||prefixed.form!==null)throw 'HTML namespace local brand';for(var bad of [doc.createElementNS(html,'LEGEND'),doc.createElementNS('urn:foreign','legend'),document.getElementById('fieldset'),Object.create(P)]){var caught=false;try{get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'distinct genuine brand';}var keys=0;for(var key in x){if(key==='form')keys++;}if(keys!==1)throw 'canonical inherited enumeration';delete window.HTMLLegendElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||Object.prototype.toString.call(x)!=='[object HTMLLegendElement]'||get.call(x)!==document.getElementById('owner'))throw 'saved canonical roots';");}
#[test]
fn legend_form_saved_child_origin_precedes_reads_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var x=document.getElementById('legend'),owner=document.getElementById('owner'),C=frame.contentWindow.HTMLLegendElement,get=Object.getOwnPropertyDescriptor(C.prototype,'form').get;if(C===HTMLLegendElement||get.call(x)!==owner)throw 'captured legend getter';");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.set_location(&crate::navigation::address("https://other-legend-form.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let e=p.runtime.execute("get.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.set_location(&crate::navigation::address("https://legend-form.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x)!==owner)throw 'captured legend getter recovery';");}
#[test]
fn legend_form_actual_exact_id_blocker_and_parent_namespace(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),fieldset=document.getElementById('fieldset'),other=document.getElementById('other'),blocker=document.createElement('div');other.id='A\ud800z';fieldset.setAttribute('form','A\ud800z');if(x.form!==other)throw 'exact actual owner';blocker.id='A\ud800z';other.parentNode.insertBefore(blocker,other);if(x.form!==null)throw 'first exact ID blocker';blocker.parentNode.removeChild(blocker);if(x.form!==other)throw 'blocker removal recovery';fieldset.setAttribute('form','A\ufffdz');if(x.form!==null)throw 'no scalar alias';var doc=new Document(),html='http://www.w3.org/1999/xhtml',legend=doc.createElementNS(html,'legend'),foreign=doc.createElementNS('urn:foreign','fieldset');foreign.appendChild(legend);if(legend.form!==null)throw 'foreign parent no owner';"#);}
#[test]
fn legend_form_native_explicit_owner_refusal_and_fresh_recovery(){for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"document.getElementById('fieldset').setAttribute('form','other');");let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("legend")).unwrap();let other=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("other")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.copy_work=0,3=>p.state.limits.host.string_bytes=0,_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.legend_form_get(node_handle(n));if mode==3{assert!(matches!(result.unwrap(),Value::Host(owner)if owner==node_handle(other)));}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=1024;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.legend_form_get(node_handle(n)).unwrap(),Value::Host(owner)if owner==node_handle(other)));}}
#[test]
fn legend_form_inert_refusal_observation_and_fresh_recovery(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),owner=doc.createElementNS(html,'form'),fieldset=doc.createElementNS(html,'fieldset'),x=doc.createElementNS(html,'legend');doc.appendChild(root);root.appendChild(owner);root.appendChild(fieldset);fieldset.appendChild(x);owner.id='target';fieldset.setAttribute('form','target');var watch=new MutationObserver(function(){});watch.observe(fieldset,{attributes:true,childList:true,subtree:true});x.form;");let limit=p.state.retained_limit;let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.copy_work=0,_=>p.state.retained_limit=p.state.retained};let e=p.runtime.execute("x.form;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.form!==owner||watch.takeRecords().length)throw 'fresh inert legend recovery';");}}

#[test]
fn legend_form_ancestor_read_needs_no_copy_string_or_new_retained_storage(){let(mut d,mut f,mut p)=fixture();let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("legend")).unwrap();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("owner")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();p.state.copy_work=0;p.state.limits.host.string_bytes=0;p.state.retained_limit=p.state.retained;let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.legend_form_get(node_handle(n)).unwrap();assert!(matches!(value,Value::Host(actual)if actual==node_handle(owner)));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}

#[test]
fn legend_form_deferred_collection_named_item_preserves_descriptor_brand_and_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var P=HTMLCollection.prototype,a=Object.getOwnPropertyDescriptor(P,'namedItem'),method=a.value,forms=document.body.children;if(!a.enumerable||!a.writable||!a.configurable||typeof method!=='function'||method.name!=='namedItem'||method.length!==1||P.namedItem!==method||forms.namedItem!==method||method.call(forms,'owner')!==document.getElementById('owner'))throw 'native namedItem data descriptor';var caught=false;try{method.call(document.getElementById('legend'),'owner');}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine collection receiver';Object.freeze(P);if(P.namedItem!==method||Object.getOwnPropertyDescriptor(P,'namedItem').writable||Object.getOwnPropertyDescriptor(P,'namedItem').configurable)throw 'stable frozen namedItem method';");}
